COMMENT ON FUNCTION community.get_filtered_posts IS 'Fetches filtered posts with range-based pagination, tag filtering, and optional my-posts-only filter. Returns a single JSON object with posts data and total count.'; -- Create enums for activity types
CREATE TYPE community.activity_entity_type AS ENUM (
    'post',
    'comment'
);

CREATE TYPE community.activity_action AS ENUM (
    'created',
    'commented',
    'replied'
);

-- Create activities table
create table community.activities (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id text NOT NULL REFERENCES public.users(id),
    recipient_id text REFERENCES public.users(id),
    entity_type community.activity_entity_type NOT NULL,
    entity_id uuid NOT NULL,
    action community.activity_action NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    is_read boolean DEFAULT false NOT NULL
);

-- Add indexes for better query performance
CREATE INDEX idx_activities_recipient_unread ON community.activities(recipient_id) WHERE NOT is_read;
CREATE INDEX idx_activities_actor ON community.activities(actor_id);
CREATE INDEX idx_activities_entity ON community.activities(entity_type, entity_id);
CREATE INDEX idx_activities_created_at ON community.activities(created_at DESC);

-- Create function for post activities
CREATE FUNCTION community.create_post_activity()
RETURNS trigger AS $$
BEGIN
    INSERT INTO community.activities (
        actor_id,
        entity_type,
        entity_id,
        action
    ) VALUES (
        NEW.user_id,
        'post'::community.activity_entity_type,
        NEW.id,
        'created'::community.activity_action
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create function for comment activities
CREATE FUNCTION community.create_comment_activity()
RETURNS trigger AS $$
DECLARE
    v_post_author_id text;
    v_parent_comment_author_id text;
BEGIN
    -- Don't create activity if the actor would be the recipient
    IF NEW.parent_comment_id IS NULL THEN
        -- Direct comment on post
        SELECT user_id INTO v_post_author_id
        FROM community.posts
        WHERE id = NEW.post_id;

        -- Only create activity if the commenter is not the post author
        IF NEW.user_id <> v_post_author_id THEN
            INSERT INTO community.activities (
                actor_id,
                recipient_id,
                entity_type,
                entity_id,
                action
            ) VALUES (
                NEW.user_id,
                v_post_author_id,
                'comment'::community.activity_entity_type,
                NEW.id,
                'commented'::community.activity_action
            );
        END IF;
    ELSE
        -- Reply to comment
        SELECT user_id INTO v_parent_comment_author_id
        FROM community.comments
        WHERE id = NEW.parent_comment_id;

        -- Only create activity if the replier is not the parent comment author
        IF NEW.user_id <> v_parent_comment_author_id THEN
            INSERT INTO community.activities (
                actor_id,
                recipient_id,
                entity_type,
                entity_id,
                action
            ) VALUES (
                NEW.user_id,
                v_parent_comment_author_id,
                'comment'::community.activity_entity_type,
                NEW.id,
                'replied'::community.activity_action
            );
        END IF;
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error but don't prevent comment creation
        RAISE WARNING 'Error creating activity for comment %: %', NEW.id, SQLERRM;
        RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create triggers
CREATE TRIGGER after_post_created
    AFTER INSERT ON community.posts
    FOR EACH ROW
    EXECUTE FUNCTION community.create_post_activity();

CREATE TRIGGER after_comment_created
    AFTER INSERT ON community.comments
    FOR EACH ROW
    EXECUTE FUNCTION community.create_comment_activity();

-- Add RLS policies
ALTER TABLE community.activities ENABLE ROW LEVEL SECURITY;

-- Users can see activities where they are the recipient or actor
CREATE POLICY "Users can see their own activities"
    ON community.activities
    FOR ALL
    USING (
        actor_id = auth.uid()::text
        OR recipient_id = auth.uid()::text
        OR recipient_id IS NULL  -- Allow viewing broadcast activities (post creations)
    );

-- Grant permissions
GRANT SELECT ON community.activities TO authenticated;
GRANT SELECT ON community.activities TO anon;

-- Add helpful comments
COMMENT ON TABLE community.activities IS 'Stores activity events for posts and comments';
COMMENT ON COLUMN community.activities.entity_type IS 'Type of entity this activity relates to (post or comment)';
COMMENT ON COLUMN community.activities.entity_id IS 'ID of the related entity (post_id or comment_id)';
COMMENT ON COLUMN community.activities.action IS 'Type of action (created, commented, replied)';
COMMENT ON COLUMN community.activities.actor_id IS 'User who performed the action';
COMMENT ON COLUMN community.activities.recipient_id IS 'User who should be notified of this activity (null for broadcast activities)'; set check_function_bodies = off;

CREATE OR REPLACE FUNCTION community.get_filtered_posts(start_range integer, end_range integer, tag_ids uuid[] DEFAULT NULL::uuid[], only_my_posts boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'community', 'public'
AS $function$DECLARE
    v_user_id text;
    v_total_count bigint;
    v_result jsonb;
BEGIN
    -- Get authenticated user's ID if only_my_posts is true
    IF only_my_posts THEN
        SELECT u.id INTO v_user_id
        FROM users u
        WHERE u.auth_id = auth.uid();

        IF v_user_id IS NULL THEN
            RAISE EXCEPTION 'User not found';
        END IF;
    END IF;

    -- Get total count first
    WITH base_query AS (
        SELECT DISTINCT p.id
        FROM community.posts p
        LEFT JOIN community.post_tags pt ON pt.post_id = p.id
        WHERE NOT p.is_hidden
        AND (v_user_id IS NULL OR p.user_id = v_user_id)
        AND (
            tag_ids IS NULL 
            OR array_length(tag_ids, 1) IS NULL 
            OR pt.tag_id = ANY(tag_ids)
        )
    )
    SELECT COUNT(*) INTO v_total_count FROM base_query;

    -- Get posts data and return as single JSON object
    WITH filtered_posts AS (
        SELECT DISTINCT p.*
        FROM community.posts p
        LEFT JOIN community.post_tags pt ON pt.post_id = p.id
        WHERE NOT p.is_hidden
        AND (CASE WHEN only_my_posts THEN p.user_id = v_user_id ELSE true END)
        AND (
            tag_ids IS NULL 
            OR array_length(tag_ids, 1) IS NULL 
            OR pt.tag_id = ANY(tag_ids)
        )
        ORDER BY p.is_pinned DESC, p.created_at DESC
        OFFSET start_range LIMIT (end_range - start_range + 1)
    ),
    post_data AS (
        SELECT 
            p.id,
            p.user_id,
            p.title,
            p.content_type,
            p.body,
            p.video_url,
            p.is_pinned,
            p.is_hidden,
            p.is_flagged_by_llm,
            p.view_count,
            p.created_at,
            p.updated_at,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'tag', jsonb_build_object(
                            'id', t.id,
                            'name', t.name,
                            'type', t.type,
                            'color', t.color
                        )
                    )
                )
                FROM community.post_tags pt
                JOIN community.tags t ON t.id = pt.tag_id
                WHERE pt.post_id = p.id
            ) as post_tags,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'emoji', r.emoji,
                        'user_id', r.user_id,
                        'post_id', r.post_id
                    )
                )
                FROM community.reactions r
                WHERE r.post_id = p.id
            ) as reactions,
            (
                SELECT COUNT(*)
                FROM community.comments c
                WHERE c.post_id = p.id
            ) as comments_count
        FROM filtered_posts p
    )
    SELECT jsonb_build_object(
        'data', COALESCE(jsonb_agg(to_jsonb(post_data.*)), '[]'::jsonb),
        'total_count', v_total_count
    ) INTO v_result
    FROM post_data;

    RETURN v_result;
END;$function$
;


create policy "Public policy"
on "public"."users"
as permissive
for select
to public
using (true);



-- Add RPC function for getting activity feed
CREATE OR REPLACE FUNCTION community.get_activity_feed(
    start_range int,                    -- Start of range (inclusive)
    end_range int                       -- End of range (inclusive)
)
RETURNS TABLE (
    id uuid,
    created_at timestamptz,
    is_read boolean,
    message text,
    entity_type community.activity_entity_type,
    entity_id uuid,
    post_id uuid,
    action community.activity_action
) 
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = community, public
AS $$
DECLARE
    v_user_id text;
BEGIN
    -- Get the authenticated user's ID
    SELECT u.id INTO v_user_id
    FROM public.users u
    WHERE u.auth_id = auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    RETURN QUERY
    SELECT 
        a.id,
        a.created_at,
        a.is_read,
        CASE 
            WHEN a.action = 'created' THEN 
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 'You created a new post "' || p.title || '"'
                    ELSE actor.name || ' created a new post "' || p.title || '"'
                END
            WHEN a.action = 'commented' THEN
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 'You commented on your post saying "' || c.body || '"'
                    ELSE actor.name || ' commented on your post saying "' || c.body || '"'
                END
            WHEN a.action = 'replied' THEN
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 'You replied to your comment saying "' || c.body || '"'
                    ELSE actor.name || ' replied to your comment saying "' || c.body || '"'
                END
        END,
        a.entity_type,
        a.entity_id,
        COALESCE(c.post_id, p.id) as post_id,
        a.action
    FROM community.activities a
    JOIN public.users actor ON actor.id = a.actor_id
    LEFT JOIN community.posts p ON 
        (a.entity_type = 'post' AND a.entity_id = p.id)
    LEFT JOIN community.comments c ON 
        (a.entity_type = 'comment' AND a.entity_id = c.id)
    WHERE a.recipient_id = v_user_id
    ORDER BY a.created_at DESC
    OFFSET start_range LIMIT (end_range - start_range + 1);
END;
$$;

-- Grant execute permissions
GRANT EXECUTE ON FUNCTION community.get_activity_feed TO authenticated;

-- Add helpful comment
COMMENT ON FUNCTION community.get_activity_feed IS 'Returns paginated activity feed for the authenticated user with formatted messages'; -- Drop existing trigger and function
