-- This migration adds deletion activity tracking to the existing activity system
-- It builds upon:
-- 1. migrations/20250221113136_add_activities.sql - which created the activities table and initial triggers
-- 2. migrations/20250207000002_add_delete_post_rpc.sql - which created the deleted_posts_log table
-- 3. migrations/20250224064339_add_activity_feed_rpc.sql - which created the get_activity_feed function

-- Add 'deleted' action to the enum
ALTER TYPE community.activity_action ADD VALUE IF NOT EXISTS 'deleted' AFTER 'replied';

-- Create function for post deletion activities
CREATE OR REPLACE FUNCTION community.create_post_deletion_activity()
RETURNS trigger AS $$
BEGIN
    -- Create activity for the post author (they deleted their own post)
    INSERT INTO community.activities (
        actor_id,
        recipient_id,
        entity_type,
        entity_id,
        action
    ) VALUES (
        OLD.user_id,
        OLD.user_id,
        'post'::community.activity_entity_type,
        OLD.id,
        'deleted'::community.activity_action
    );
    
    -- Note: The post is already being logged in deleted_posts_log by the delete_post RPC
    
    RETURN OLD;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error but don't prevent post deletion
        RAISE WARNING 'Error creating deletion activity for post %: %', OLD.id, SQLERRM;
        RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create function for comment deletion activities
CREATE OR REPLACE FUNCTION community.create_comment_deletion_activity()
RETURNS trigger AS $$
DECLARE
    v_post_author_id text;
    v_post_title text;
BEGIN
    -- Get post information
    SELECT p.user_id, p.title INTO v_post_author_id, v_post_title
    FROM community.posts p
    WHERE p.id = OLD.post_id;
    
    -- Create activity for the comment author (they deleted their own comment)
    INSERT INTO community.activities (
        actor_id,
        recipient_id,
        entity_type,
        entity_id,
        action
    ) VALUES (
        OLD.user_id,
        OLD.user_id,
        'comment'::community.activity_entity_type,
        OLD.id,
        'deleted'::community.activity_action
    );
    
    -- If the comment author is not the post author, notify the post author
    IF OLD.user_id <> v_post_author_id THEN
        INSERT INTO community.activities (
            actor_id,
            recipient_id,
            entity_type,
            entity_id,
            action
        ) VALUES (
            OLD.user_id,
            v_post_author_id,
            'comment'::community.activity_entity_type,
            OLD.id,
            'deleted'::community.activity_action
        );
    END IF;
    
    RETURN OLD;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error but don't prevent comment deletion
        RAISE WARNING 'Error creating deletion activity for comment %: %', OLD.id, SQLERRM;
        RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create triggers
DROP TRIGGER IF EXISTS before_post_deleted ON community.posts;
CREATE TRIGGER before_post_deleted
    BEFORE DELETE ON community.posts
    FOR EACH ROW
    EXECUTE FUNCTION community.create_post_deletion_activity();

DROP TRIGGER IF EXISTS before_comment_deleted ON community.comments;
CREATE TRIGGER before_comment_deleted
    BEFORE DELETE ON community.comments
    FOR EACH ROW
    EXECUTE FUNCTION community.create_comment_deletion_activity();

-- Update the existing activity feed RPC to handle deletion messages
-- We're only adding the 'deleted' case to the CASE statement, not recreating the entire function
CREATE OR REPLACE FUNCTION community.get_activity_feed(
    start_range int,
    end_range int
)
RETURNS TABLE (
    id uuid,
    created_at timestamptz,
    is_read boolean,
    message text,
    entity_type community.activity_entity_type,
    entity_id uuid,
    post_id uuid,
    action community.activity_action
) 
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = community, public
AS $$
DECLARE
    v_user_id text;
BEGIN
    -- Get the authenticated user's ID
    SELECT u.id INTO v_user_id
    FROM public.users u
    WHERE u.auth_id = auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    RETURN QUERY
    WITH post_titles AS (
        -- Get titles for both existing and deleted posts
        SELECT 
            p.id AS post_id,
            p.title AS title
        FROM community.posts p
        UNION ALL
        SELECT 
            dl.id AS post_id,
            dl.title AS title
        FROM community.deleted_posts_log dl
    )
    SELECT 
        a.id,
        a.created_at,
        a.is_read,
        CASE 
            WHEN a.action = 'created' THEN 
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 
                        'You created a new post "' || 
                        COALESCE(
                            (SELECT pt.title FROM post_titles pt WHERE pt.post_id = a.entity_id),
                            'Untitled'
                        ) || '"'
                    ELSE 
                        actor.name || ' created a new post "' || 
                        COALESCE(
                            (SELECT pt.title FROM post_titles pt WHERE pt.post_id = a.entity_id),
                            'Untitled'
                        ) || '"'
                END
            WHEN a.action = 'commented' THEN
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 'You commented on your post saying "' || c.body || '"'
                    ELSE actor.name || ' commented on your post saying "' || c.body || '"'
                END
            WHEN a.action = 'replied' THEN
                CASE 
                    WHEN a.actor_id = a.recipient_id THEN 'You replied to your comment saying "' || c.body || '"'
                    ELSE actor.name || ' replied to your comment saying "' || c.body || '"'
                END
            WHEN a.action = 'deleted' THEN
                CASE 
                    WHEN a.entity_type = 'post' THEN
                        CASE 
                            WHEN a.actor_id = a.recipient_id THEN 
                                'You deleted your post "' || 
                                COALESCE(
                                    (SELECT pt.title FROM post_titles pt WHERE pt.post_id = a.entity_id),
                                    'Untitled'
                                ) || '"'
                            ELSE 
                                actor.name || ' deleted their post "' || 
                                COALESCE(
                                    (SELECT pt.title FROM post_titles pt WHERE pt.post_id = a.entity_id),
                                    'Untitled'
                                ) || '"'
                        END
                    WHEN a.entity_type = 'comment' THEN
                        CASE 
                            WHEN a.actor_id = a.recipient_id THEN 'You deleted your comment'
                            ELSE actor.name || ' deleted their comment on your post'
                        END
                END
        END,
        a.entity_type,
        a.entity_id,
        COALESCE(c.post_id, p.id, 
            -- For deleted posts, the entity_id is the post id
            CASE WHEN a.entity_type = 'post' AND a.action = 'deleted' THEN a.entity_id ELSE NULL END
        ) as post_id,
        a.action
    FROM community.activities a
    JOIN public.users actor ON actor.id = a.actor_id
    LEFT JOIN community.posts p ON 
        (a.entity_type = 'post' AND a.entity_id = p.id)
    LEFT JOIN community.comments c ON 
        (a.entity_type = 'comment' AND a.entity_id = c.id)
    WHERE a.recipient_id = v_user_id
    ORDER BY a.created_at DESC
    OFFSET start_range LIMIT (end_range - start_range + 1);
END;
$$;

-- Add helpful comments
COMMENT ON FUNCTION community.create_post_deletion_activity IS 'Creates an activity record when a post is deleted';
COMMENT ON FUNCTION community.create_comment_deletion_activity IS 'Creates activity records when a comment is deleted'; alter table "community"."posts" add column "thumbnail_url" text;


CREATE OR REPLACE FUNCTION community.create_post_with_tags(
  p_title TEXT,
  p_content_type TEXT,
  p_body TEXT,
  p_video_url TEXT,
  p_thumbnail_url TEXT, -- New parameter added
  p_user_id TEXT,
  p_tags TEXT[]
) RETURNS UUID 
  SECURITY DEFINER
  AS $$
DECLARE
  v_post_id uuid;
  v_tag_id uuid;
  v_tag TEXT;
BEGIN
  -- Input validation
  IF p_title IS NULL OR p_content_type IS NULL THEN
    RAISE EXCEPTION 'Title and content_type are required fields';
  END IF;

  IF p_content_type NOT IN ('text', 'video') THEN
    RAISE EXCEPTION 'Invalid content_type. Must be either text or video';
  END IF;

  IF p_content_type = 'text' AND p_body IS NULL THEN
    RAISE EXCEPTION 'Body is required for text posts';
  END IF;

  IF p_content_type = 'video' AND p_video_url IS NULL THEN
    RAISE EXCEPTION 'Video URL is required for video posts';
  END IF;

  -- Log the start of the operation
  RAISE LOG 'Creating new post with title: %, content_type: %, user_id: %', p_title, p_content_type, p_user_id;

  -- First create the post
  INSERT INTO community.posts (
    title,
    content_type,
    body,
    video_url,
    thumbnail_url, -- New column added
    user_id,
    is_pinned,
    is_hidden,
    created_at,
    updated_at
  ) VALUES (
    p_title,
    p_content_type,
    p_body,
    p_video_url,
    p_thumbnail_url, -- New parameter included
    p_user_id,
    false,
    false,
    NOW(),
    NULL
  ) RETURNING id INTO v_post_id;

  -- Log successful post creation
  RAISE LOG 'Successfully created post with ID: %', v_post_id;

  -- Then handle each tag
  IF array_length(p_tags, 1) > 0 THEN
    FOREACH v_tag IN ARRAY p_tags
    LOOP
      -- Log tag processing
      RAISE LOG 'Processing tag: %', v_tag;

      -- Try to find existing tag or create new one
      INSERT INTO community.tags (name, created_at)
      VALUES (v_tag, NOW())
      ON CONFLICT (name) 
      DO UPDATE SET name = EXCLUDED.name
      RETURNING id INTO v_tag_id;

      -- Create post_tag connection
      INSERT INTO community.post_tags (post_id, tag_id, created_at)
      VALUES (v_post_id, v_tag_id, NOW());

      -- Log successful tag association
      RAISE LOG 'Associated tag % (ID: %) with post %', v_tag, v_tag_id, v_post_id;
    END LOOP;
  END IF;

  RETURN v_post_id;
EXCEPTION
  WHEN others THEN
    -- Log any errors that occur
    RAISE LOG 'Error in create_post_with_tags: %', SQLERRM;
    RAISE EXCEPTION 'An error occurred while creating the post: %', SQLERRM;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION community.get_filtered_posts(start_range integer, end_range integer, tag_ids uuid[] DEFAULT NULL::uuid[], only_my_posts boolean DEFAULT false, include_pinned boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'community', 'public'
AS $function$DECLARE
    v_user_id text;
    v_total_count bigint;
    v_result jsonb;
BEGIN
    -- Get authenticated user's ID if only_my_posts is true
    IF only_my_posts THEN
        SELECT u.id INTO v_user_id
        FROM users u
        WHERE u.auth_id = auth.uid();

        IF v_user_id IS NULL THEN
            RAISE EXCEPTION 'User not found';
        END IF;
    END IF;

    -- Get total count first
    WITH base_query AS (
        SELECT DISTINCT p.id
        FROM community.posts p
        LEFT JOIN community.post_tags pt ON pt.post_id = p.id
        WHERE NOT p.is_hidden
        AND (v_user_id IS NULL OR p.user_id = v_user_id)
        AND (
            tag_ids IS NULL 
            OR array_length(tag_ids, 1) IS NULL 
            OR pt.tag_id = ANY(tag_ids)
        )
    )
    SELECT COUNT(*) INTO v_total_count FROM base_query;

    -- Get posts data and return as single JSON object
    WITH filtered_posts AS (
        SELECT DISTINCT p.*
        FROM community.posts p
        LEFT JOIN community.post_tags pt ON pt.post_id = p.id
        WHERE NOT p.is_hidden
        AND (CASE WHEN only_my_posts THEN p.user_id = v_user_id ELSE true END)
        AND (include_pinned OR NOT p.is_pinned)
        AND (
            tag_ids IS NULL 
            OR array_length(tag_ids, 1) IS NULL 
            OR pt.tag_id = ANY(tag_ids)
        )
        ORDER BY p.is_pinned DESC, p.created_at DESC
        OFFSET start_range LIMIT (end_range - start_range + 1)
    ),
    post_data AS (
        SELECT 
            p.id,
            p.user_id,
            p.title,
            p.content_type,
            p.body,
            p.video_url,
            p.thumbnail_url,
            p.is_pinned,
            p.is_hidden,
            p.is_flagged_by_llm,
            p.view_count,
            p.created_at,
            p.updated_at,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'tag', jsonb_build_object(
                            'id', t.id,
                            'name', t.name,
                            'type', t.type,
                            'color', t.color
                        )
                    )
                )
                FROM community.post_tags pt
                JOIN community.tags t ON t.id = pt.tag_id
                WHERE pt.post_id = p.id
            ) as post_tags,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'emoji', r.emoji,
                        'user_id', r.user_id,
                        'post_id', r.post_id
                    )
                )
                FROM community.reactions r
                WHERE r.post_id = p.id
            ) as reactions,
            (
                SELECT COUNT(*)
                FROM community.comments c
                WHERE c.post_id = p.id
            ) as comments_count
        FROM filtered_posts p
    )
    SELECT jsonb_build_object(
        'data', COALESCE(jsonb_agg(to_jsonb(post_data.*)), '[]'::jsonb),
        'total_count', v_total_count
    ) INTO v_result
    FROM post_data;

    RETURN v_result;
END;$function$
;


