 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$BEGIN
  -- Check if a profile with the user id exists in community.profiles
  IF EXISTS (SELECT 1 FROM community.profiles WHERE id = NEW.id) THEN
    -- If profile exists, update the name and emoji
    UPDATE community.profiles
    SET 
      name = NEW.name,
      emoji = NEW.emoji
    WHERE id = NEW.id;
  END IF;
  
  RETURN NEW;
END;$function$
;

